150. #[verus_verify]
151. impl PhysMemoryManager {
152.     ///
153.     /// # Description
154.     ///
155.     /// Allocates user frames into caller-provided storage.
156.     ///
157.     /// The returned frames are not guaranteed to be physically contiguous.
158.     /// User allocations are gated by the kernel watermark: if fulfilling the request would
159.     /// leave fewer than `KERNEL_WATERMARK` free frames, the allocation is rejected.
160.     ///
161.     /// # Parameters
162.     ///
163.     /// - `count`: Number of frames to allocate.
164.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store those
165.     ///   frames' addresses. It should have sufficient capacity for `count` entries.
166.     ///
167.     /// # Return Values
168.     ///
169.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count` frames. Upon failure, an
170.     /// error is returned and any frames allocated by this call are dropped by truncating `frames`
171.     /// back to empty.
172.     ///
173.     #[verus_spec(result =>
174.         requires
175.             self.inv(),
176.             old(frames)@.len() == 0,
177.         ensures
178.             final(self).inv(),
179.             match result {
180.                 Ok(()) => {
181.                     &&& (count > 0 ==> old(self)@.user_alloc_ok(count as nat))
182.                     &&& final(frames)@.len() == count
183.                     &&& user_addr_set(final(frames)@).len() == count
184.                     &&& old(self)@.all_free(user_addr_set(final(frames)@))
185.                     &&& final(self)@ == old(self)@.book_all(user_addr_set(final(frames)@))
186.                 },
187.                 Err(_) => {
188.                     &&& final(self)@ == old(self)@
189.                     &&& final(frames)@.len() == 0
190.                 },
191.             },
192.     )]
193.     pub fn alloc_many_user_frames(
194.         &mut self,
195.         count: usize,
196.         frames: &mut Vec<UserFrame>,
197.     ) -> Result<(), Error> {
198.         proof_decl! {
199.             let ghost g_old = self@;
200.         }
201.         proof! {
202.             assert(g_old == old(self)@);
203.             assert(g_old.wf());
204.         }
205.         if !frames.is_empty() {
206.             let reason: &str = "frames vector is not empty";
207.             #[cfg(not(verus_keep_ghost))]
208.             error!("{reason}");
209.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
210.         }
211.         if frames.capacity() < count {
212.             let reason: &str = "frames vector has insufficient capacity";
213.             #[cfg(not(verus_keep_ghost))]
214.             error!("{reason}");
215.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
216.         }
217. 
218.         // A zero-sized allocation is trivially satisfied.
219.         if count == 0 {
220.             proof! {
221.                 lemma_user_addr_set_empty(frames@);
222.                 lemma_book_all_empty(g_old);
223.             }
224.             return Ok(());
225.         }
226. 
227.         Self::check_user_watermark(count)?;
228.         proof! {
229.             lemma_manager_attached(self);
230.             lemma_user_addr_set_empty(frames@);
231.             lemma_book_all_empty(g_old);
232.         }
233. 
234.         #[cfg_attr(verus_keep_ghost, verus_spec(
235.             invariant
236.                 g_old == old(self)@,
237.                 g_old.wf(),
238.                 self@.wf(),
239.                 frames@.len() == i,
240.                 user_addr_set(frames@).finite(),
241.                 user_addr_set(frames@).len() == i,
242.                 g_old.all_free(user_addr_set(frames@)),
243.                 self@ == g_old.book_all(user_addr_set(frames@)),
244.         ))]
245.         for i in 0..count {
246.             proof_decl! {
247.                 let ghost frames_pre = frames@;
248.                 let ghost set_pre = user_addr_set(frames@);
249.             }
250.             match self.upool.alloc() {
251.                 Ok(frame) => {
252.                     frames.push(frame);
253.                     proof! {
254.                         // `self.upool.alloc()` moved `frame@` (free in `g_old`, not yet booked)
255.                         // out of the partition; fold it into the accumulated address set.
256.                         lemma_user_addr_set_push(frames_pre, frame);
257.                         lemma_book_all_alloc_one(g_old, set_pre, frame@);
258.                     }
259.                 },
260.                 Err(error) => {
261.                     frames.clear();
262.                     proof! {
263.                         lemma_user_bulk_err_restored(self, g_old);
264.                     }
265.                     return Err(error);
266.                 },
267.             }
268.         }
269.         Ok(())
270.     }
271. 
272.     ///
273.     /// # Description
274.     ///
275.     /// Allocates a single user frame, applying the same kernel watermark check as
276.     /// [`Self::alloc_many_user_frames`]. This is the single-frame fast path used on
277.     /// hot paths such as copy-on-write fault resolution, where allocating an
278.     /// intermediate [`Vec`] would be wasteful.
279.     ///
280.     /// # Returns
281.     ///
282.     /// Upon success, a [`UserFrame`] is returned. Upon failure, an error is returned
283.     /// instead.
284.     ///
285.     #[verus_spec(result =>
286.         requires
287.             self.inv(),
288.         ensures
289.             final(self).inv(),
290.             match result {
291.                 Ok(uf) => {
292.                     &&& old(self)@.user_alloc_ok(1)
293.                     &&& old(self)@.free_frames.contains(uf@)
294.                     &&& final(self)@ == old(self)@.alloc_one(uf@)
295.                 },
296.                 Err(_) => {
297.                     &&& final(self)@ == old(self)@
298.                     &&& !old(self)@.user_alloc_ok(1)
299.                 },
300.             },
301.     )]
302.     pub fn alloc_user_frame(&mut self) -> Result<UserFrame, Error> {
303.         proof! {
304.             lemma_manager_attached(self);
305.         }
306.         Self::check_user_watermark(1)?;
307.         self.upool.alloc()
308.     }
309. 
310.     ///
311.     /// # Description
312.     ///
313.     /// Rejects user allocations of `count` frames that would breach the kernel
314.     /// watermark, i.e. that would drop the number of free frames below
315.     /// [`config::kernel::KERNEL_WATERMARK`].
316.     ///
317.     /// # Parameters
318.     ///
319.     /// - `count`: Number of user frames the caller intends to allocate.
320.     ///
321.     /// # Returns
322.     ///
323.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
324.     ///
325.     #[verus_spec(result =>
326.         ensures
327.             match result {
328.                 Ok(()) => crate::mm::phys::phys_view().frames.free_count()
329.                     >= count as nat + spec_kernel_watermark(),
330.                 Err(_) => crate::mm::phys::phys_view().frames.free_count()
331.                     < count as nat + spec_kernel_watermark(),
332.             },
333.     )]
334.     fn check_user_watermark(count: usize) -> Result<(), Error> {
335.         // VERUS DEVIATION (Verus-required, semantics-preserving): bind the current free-frame
336.         // count *before* the watermark-threshold computation. `frame::free_count()` is a pure read
337.         // whose `usize` result pins `phys_view().frames.free_count() <= usize::MAX`; the
338.         // watermark-overflow error path needs that bound to conclude the free count is below the
339.         // (overflowing) `watermark + count` threshold. Same call, same result; on the rare
340.         // overflow path it is now evaluated unconditionally (one extra O(1) bitmap read).
341.         let free: usize = frame::free_count();
342.         let watermark_threshold: usize = kernel_watermark()
343.             .checked_add(count)
344.             .ok_or_else(|| {
345.                 let reason: &str = "watermark + count overflow";
346.                 #[cfg(not(verus_keep_ghost))]
347.                 error!("{reason}");
348.                 Error::new(ErrorCode::InvalidArgument, reason)
349.             })?;
350.         if free < watermark_threshold {
351.             let reason: &str = "would breach kernel watermark";
352.             #[cfg(not(verus_keep_ghost))]
353.             error!("{reason}");
354.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
355.         }
356.         Ok(())
357.     }
358. 
359.     ///
360.     /// # Description
361.     ///
362.     /// Allocates a kernel frame.
363.     ///
364.     /// Kernel allocations bypass the watermark — no artificial ceiling.
365.     ///
366.     /// # Return Values
367.     ///
368.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
369.     ///
370.     #[verus_spec(result =>
371.         requires
372.             self.inv(),
373.         ensures
374.             final(self).inv(),
375.             match result {
376.                 Ok(kf) => {
377.                     &&& old(self)@.free_frames.contains(kf@)
378.                     &&& final(self)@ == old(self)@.alloc_one(kf@)
379.                 },
380.                 Err(_) => final(self)@ == old(self)@,
381.             },
382.     )]
383.     pub fn alloc_kernel_frame(&mut self) -> Result<KernelFrame, Error> {
384.         proof_decl! {
385.             let ghost g_old = self@;
386.         }
387.         let frame_addr: FrameAddress = frame::alloc()?;
388.         let result: Result<KernelFrame, Error> = KernelFrame::new(frame_addr).inspect_err(|e| {
389.             #[cfg(not(verus_keep_ghost))]
390.             warn!("failed to wrap frame after KernelFrame::new failure: {e:?}");
391.             if let Err(free_err) = frame::free(frame_addr) {
392.                 #[cfg(not(verus_keep_ghost))]
393.                 warn!("failed to free frame after KernelFrame::new failure: {free_err:?}");
394.             }
395.         });
396.         proof! {
397.             if result is Ok {
398.                 lemma_kernel_alloc_one(g_old, self@, result->Ok_0@);
399.             }
400.         }
401.         result
402.     }
403. 
404.     ///
405.     /// # Description
406.     ///
407.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
408.     ///
409.     /// Kernel stacks require physically contiguous frames because the kernel uses identity
410.     /// mapping and the hardware stack pointer traverses the region linearly.
411.     /// Kernel allocations bypass the watermark — no artificial ceiling.
412.     ///
413.     /// # Parameters
414.     ///
415.     /// - `count`: Number of frames to allocate.
416.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store
417.     ///   those frames' addresses.
418.     ///
419.     /// # Return Values
420.     ///
421.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count`
422.     /// contiguous entries. Upon failure, an error is returned instead.
423.     ///
424.     #[verus_spec(result =>
425.         requires
426.             self.inv(),
427.             old(frames)@.len() == 0,
428.             count > 0,
429.         ensures
430.             final(self).inv(),
431.             match result {
432.                 Ok(()) => {
433.                     &&& final(frames)@.len() == count
434.                     &&& kernel_frames_contiguous(final(frames)@, count as nat)
435.                     &&& old(self)@.all_free(kernel_addr_set(final(frames)@))
436.                     &&& final(self)@ == old(self)@.book_all(kernel_addr_set(final(frames)@))
437.                 },
438.                 Err(_) => {
439.                     &&& final(self)@ == old(self)@
440.                     &&& final(frames)@.len() == 0
441.                 },
442.             },
443.     )]
444.     pub fn alloc_many_kernel_frames(
445.         &mut self,
446.         count: usize,
447.         frames: &mut Vec<KernelFrame>,
448.     ) -> Result<(), Error> {
449.         proof_decl! {
450.             let ghost g_old = self@;
451.         }
452.         proof! {
453.             assert(g_old == old(self)@);
454.             assert(g_old.wf());
455.         }
456.         // Check if caller-provided vector is not empty.
457.         if !frames.is_empty() {
458.             let reason: &str = "frames vector is not empty";
459.             #[cfg(not(verus_keep_ghost))]
460.             error!("{reason}");
461.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
462.         }
463.         if frames.capacity() < count {
464.             let reason: &str = "frames vector has insufficient capacity";
465.             #[cfg(not(verus_keep_ghost))]
466.             error!("{reason}");
467.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
468.         }
469. 
470.         let base_addr: FrameAddress = frame::alloc_contiguous(count)?;
471.         let base_raw: usize = base_addr.into_raw_value();
472.         #[cfg_attr(verus_keep_ghost, verus_spec(
473.             invariant
474.                 g_old == old(self)@,
475.                 g_old.wf(),
476.                 self@ == g_old,
477.                 base_raw as int == base_addr@,
478.                 base_raw as int + (count as int) * spec_page_size() <= usize::MAX as int,
479.         ))]
480.         for i in 0..count {
481.             proof! {
482.                 lemma_contig_no_overflow(base_raw, i, count);
483.             }
484.             let raw_addr: usize = base_raw + i * mem::PAGE_SIZE;
485.             match FrameAddress::from_raw_value(raw_addr).and_then(KernelFrame::new) {
486.                 Ok(kf) => frames.push(kf),
487.                 Err(e) => {
488.                     // Drop already-wrapped frames (frees them via KernelFrame::Drop).
489.                     frames.clear();
490.                     // Free remaining un-wrapped frames from the contiguous allocation.
491.                     #[cfg_attr(verus_keep_ghost, verus_spec(
492.                         invariant
493.                             g_old == old(self)@,
494.                             g_old.wf(),
495.                             self@ == g_old,
496.                             base_raw as int == base_addr@,
497.                             base_raw as int + (count as int) * spec_page_size()
498.                                 <= usize::MAX as int,
499.                     ))]
500.                     for j in i..count {
501.                         proof! {
502.                             lemma_contig_no_overflow(base_raw, j, count);
503.                         }
504.                         let leak_raw: usize = base_raw + j * mem::PAGE_SIZE;
505.                         if let Ok(fa) = FrameAddress::from_raw_value(leak_raw) {
506.                             if let Err(e) = frame::free(fa) {
507.                                 #[cfg(not(verus_keep_ghost))]
508.                                 warn!("failed to free leaked frame {fa:?}: {e:?}");
509.                             }
510.                         }
511.                     }
512.                     return Err(e);
513.                 },
514.             }
515.         }
516.         proof! {
517.             lemma_kernel_alloc_contiguous(g_old, self@, frames@, count as nat);
518.         }
519.         Ok(())
520.     }
521. }
522. 
