527. // External-bottom trust boundary: `config::kernel::KERNEL_WATERMARK` is generated by the `config`
528. // crate's `build.rs` (from `kernel_config.toml`) and lives in a non-Verus dependency crate, so
529. // Verus cannot resolve its value. This accessor ties the runtime constant to the abstract
530. // `spec_kernel_watermark()`. Listed in `verus-ai-logs/tcb-allowed.md`.
531. #[verus_verify(external_body)]
532. #[verus_spec(ret =>
533.     ensures
534.         ret as nat == spec_kernel_watermark(),
535. )]
536. fn kernel_watermark() -> usize {
537.     config::kernel::KERNEL_WATERMARK
538. }
