 /// are not modeled in exec, so the restoration is asserted here.
 #[verus_verify(external_body)]
 pub proof fn lemma_user_bulk_err_restored(m: &PhysMemoryManager, pre: FrameAllocView)
     requires
         pre.wf(),
     ensures
         m@ == pre,
 {
 }

